def validar_nif(nif: str) -> bool:
    """
    Valida NIF português com checksum mod 11.
    Template AI Provider OS - Workplace
    """
    if not nif or not isinstance(nif, str):
        return False
    nif = nif.strip().replace(" ", "")
    if len(nif) != 9 or not nif.isdigit():
        return False
    # Primeiro dígito 1,2,3,5,6,8,9
    if nif[0] not in "1235689":
        return False
    # Checksum mod 11
    total = sum(int(nif[i]) * (9 - i) for i in range(8))
    resto = total % 11
    digito = 0 if resto < 2 else 11 - resto
    return digito == int(nif[8])

def main():
    testes = ["123456789", "501442600", "123456780", "", "abc"]
    for t in testes:
        print(f"{t}: {validar_nif(t)}")

if __name__ == "__main__":
    main()

