from main import validar_nif

def test_valid():
    assert validar_nif("501442600") == True

def test_invalid_length():
    assert validar_nif("123") == False

def test_invalid_chars():
    assert validar_nif("abc") == False
    assert validar_nif("") == False
    assert validar_nif(None) == False

def test_checksum():
    assert validar_nif("123456789") == True
